"""Persistent treap with immutable nodes for cheap snapshot/restore.

Nodes are tuples ``(key, prio, size, byt, val, left, right)`` where ``size`` is
the node count of the subtree and ``byt`` the summed byte weight of the subtree.
Updates copy only the nodes along one root-to-leaf path, so saved tree roots
stay valid forever; a snapshot is then just a saved root reference.
"""
import random

_POOL = [x.getrandbits(30) for x in (random.Random(0x5EED5EED),) for _ in range(65536)]
_counter = [0]


def _prio():
    c = _counter[0]
    _counter[0] = c + 1
    return _POOL[c & 65535]


def size(t):
    return t[2] if t is not None else 0


def bytsum(t):
    return t[3] if t is not None else 0


def _mk(key, prio, own, val, left, right):
    return (key, prio, size(left) + size(right) + 1,
            own + bytsum(left) + bytsum(right), val, left, right)


def _own(t):
    return t[3] - bytsum(t[5]) - bytsum(t[6])


def split(t, key):
    """Split into (keys < key, keys >= key)."""
    if t is None:
        return (None, None)
    if t[0] < key:
        lo, hi = split(t[6], key)
        return (_mk(t[0], t[1], _own(t), t[4], t[5], lo), hi)
    lo, hi = split(t[5], key)
    return (lo, _mk(t[0], t[1], _own(t), t[4], hi, t[6]))


def merge(a, b):
    """Merge two trees where every key of a is below every key of b."""
    if a is None:
        return b
    if b is None:
        return a
    if a[1] > b[1]:
        return _mk(a[0], a[1], _own(a), a[4], a[5], merge(a[6], b))
    return _mk(b[0], b[1], _own(b), b[4], merge(a, b[5]), b[6])


def insert(t, key, val, own=0):
    """Insert (or replace) ``key`` with value ``val`` and byte weight ``own``."""
    node = _mk(key, _prio(), own, val, None, None)
    return _place(t, node)


def _place(t, node):
    if t is None:
        return node
    if node[1] > t[1]:
        lo, hi = split(t, node[0])
        return _mk(node[0], node[1], node[3], node[4], lo, hi)
    if node[0] < t[0]:
        return _mk(t[0], t[1], _own(t), t[4], _place(t[5], node), t[6])
    if t[0] < node[0]:
        return _mk(t[0], t[1], _own(t), t[4], t[5], _place(t[6], node))
    return _mk(node[0], node[1], node[3], node[4], t[5], t[6])


def delete(t, key):
    if t is None:
        return None
    if key < t[0]:
        return _mk(t[0], t[1], _own(t), t[4], delete(t[5], key), t[6])
    if t[0] < key:
        return _mk(t[0], t[1], _own(t), t[4], t[5], delete(t[6], key))
    return merge(t[5], t[6])


def find(t, key):
    while t is not None:
        if key == t[0]:
            return t[4]
        t = t[5] if key < t[0] else t[6]
    return None


def count_lt(t, key):
    """Number of keys strictly below ``key``."""
    c = 0
    while t is not None:
        if t[0] < key:
            c += 1 + size(t[5])
            t = t[6]
        else:
            t = t[5]
    return c


def pop_min(t):
    """Return (key, val, rest) removing the smallest key; t must be nonempty."""
    if t[5] is None:
        return (t[0], t[4], t[6])
    key, val, rest = pop_min(t[5])
    return (key, val, _mk(t[0], t[1], _own(t), t[4], rest, t[6]))


def split_size(t, k):
    """Split into (first k keys in order, remaining keys)."""
    if k <= 0:
        return (None, t)
    if t is None:
        return (None, None)
    ls = size(t[5])
    if k <= ls:
        lo, rest = split_size(t[5], k)
        return (lo, _mk(t[0], t[1], _own(t), t[4], rest, t[6]))
    lo, rest = split_size(t[6], k - ls - 1)
    return (_mk(t[0], t[1], _own(t), t[4], t[5], lo), rest)


def split_bytes(t, cap):
    """Split into (longest key-order prefix with byte weight <= cap, suffix)."""
    if t is None:
        return (None, None)
    lb = bytsum(t[5])
    own = _own(t)
    if lb + own <= cap:
        keep, drop = split_bytes(t[6], cap - lb - own)
        return (_mk(t[0], t[1], own, t[4], t[5], keep), drop)
    keep, drop = split_bytes(t[5], cap)
    return (keep, _mk(t[0], t[1], own, t[4], drop, t[6]))


def items(t):
    """In-order list of (key, val)."""
    out = []
    stack = []
    while t is not None or stack:
        while t is not None:
            stack.append(t)
            t = t[5]
        t = stack.pop()
        out.append((t[0], t[4]))
        t = t[6]
    return out


def items_desc(t):
    return list(reversed(items(t)))
