        old = self.borders
        new = list(new_borders)

        def migrate(vec):
            out = [0] * (len(new) - 1)
            for k in range(len(old) - 1):
                m = vec[k]
                b, c = old[k], old[k + 1]
                for j in range(len(new) - 1):
                    u, v = new[j], new[j + 1]

                    def cl(x):
                        return max(0, min(x, c - b))
                    out[j] += (m * cl(v - b)) // (c - b) - (m * cl(u - b)) // (c - b)
            return out

        self.C = [[migrate(self.C[l][q]) for q in range(self.M)]
                  for l in range(self.L)]
        self.H = migrate(self.H)
        self.borders = new
        log.append([i, "repartition", len(new) - 1])

    def do_cancel(self, i, pid, log):
        pkt = self.live.get(pid)
        if pkt is None:
            log.append([i, "cancel", pid, None, None, None])
            return
        stage = "fifo"
        if pkt in self.fifos[pkt.bank]:
            self.fifos[pkt.bank].remove(pkt)
        else:
            self.pifos[pkt.bank].remove(pkt)
            stage = "pifo"
        del self.live[pid]
        log.append([i, "cancel", pid, stage, pkt.bank, pkt.lag])

    def do_inspect(self, i, pid, log):
        pkt = self.live.get(pid)
        if pkt is None:
            log.append([i, "inspect", pid, None])
            return
        stage = "fifo" if pkt in self.fifos[pkt.bank] else "pifo"
        log.append([i, "inspect", pid,
                    [pkt.rank, pkt.bank, stage, pkt.length, pkt.flow, pkt.lag]])

    def snapshot(self):
        return copy.deepcopy(self.__dict__)

    def restore(self, snap):
        self.__dict__.clear()
        self.__dict__.update(copy.deepcopy(snap))

    def certificate(self):
        queues = []
        lag_pairs = []
        for q in range(self.M):
            queues.append({
                "fifo": [p.pid for p in self.fifos[q]],
                "pifo": [p.pid for p in self.pifos[q]],
