        self.pifos = [[] for _ in range(self.M)]   # lists sorted by (rank,ord)
        self.live = {}                             # pid -> RPkt
        self.saves = {}
        pol = cfg["policy"]
        self.kind = pol["kind"]
        self.fifo_time = 0
        self.levels = dict(pol.get("levels", []))
        self.weights = dict(pol.get("weights", []))
        self.finish = {f: 0 for f in self.weights}
        self.V = 0

    # policy
    def rank_of(self, pid, flow, length, flow_size):
        if self.kind == "fifo":
