from utils import run_request
from ref import Ref


def gen_borders(rng, U, max_ranges=6):
    n = rng.randint(1, max_ranges)
    pts = sorted(rng.sample(range(1, U), min(n, U - 1))) if U > 1 else []
    return [0] + pts + [U]


def gen_run(rng, ops=40):
    M = rng.randint(1, 4)
    L = rng.randint(1, 3)
