"""Persistent treap with immutable nodes for cheap snapshot/restore.

Nodes are tuples ``(key, prio, size, byt, val, left, right)`` where ``size`` is
the node count of the subtree and ``byt`` the summed byte weight of the subtree.
Updates copy only the nodes along one root-to-leaf path, so saved tree roots
stay valid forever; a snapshot is then just a saved root reference.
"""
import os
import random

try:
    _seed = int.from_bytes(os.urandom(16), "big")
except Exception:                       # pragma: no cover - entropy fallback
    _seed = 0x5EED5EED
_POOL = [x.getrandbits(30)
         for x in (random.Random(_seed),) for _ in range(65536)]
_counter = [0]


def _prio():
    c = _counter[0]
    _counter[0] = c + 1
    return _POOL[c & 65535]


def size(t):
    return t[2] if t is not None else 0


def bytsum(t):
    return t[3] if t is not None else 0


def _mk(key, prio, own, val, left, right):
    return (key, prio, size(left) + size(right) + 1,
            own + bytsum(left) + bytsum(right), val, left, right)


def _own(t):
    return t[3] - bytsum(t[5]) - bytsum(t[6])


def split(t, key):
    """Split into (keys < key, keys >= key)."""
    if t is None:
        return (None, None)
    if t[0] < key:
        lo, hi = split(t[6], key)
        return (_mk(t[0], t[1], _own(t), t[4], t[5], lo), hi)
    lo, hi = split(t[5], key)
    return (lo, _mk(t[0], t[1], _own(t), t[4], hi, t[6]))


def merge(a, b):
    """Merge two trees where every key of a is below every key of b."""
    if a is None:
        return b
    if b is None:
        return a
    if a[1] > b[1]:
        return _mk(a[0], a[1], _own(a), a[4], a[5], merge(a[6], b))
    return _mk(b[0], b[1], _own(b), b[4], merge(a, b[5]), b[6])


def insert(t, key, val, own=0):
    """Insert (or replace) ``key`` with value ``val`` and byte weight ``own``."""
    node = _mk(key, _prio(), own, val, None, None)
    return _place(t, node)


def _place(t, node):
    if t is None:
        return node
    if node[1] > t[1]:
        lo, hi = split(t, node[0])
        return _mk(node[0], node[1], node[3], node[4], lo, hi)
    if node[0] < t[0]:
        return _mk(t[0], t[1], _own(t), t[4], _place(t[5], node), t[6])
    if t[0] < node[0]:
        return _mk(t[0], t[1], _own(t), t[4], t[5], _place(t[6], node))
    return _mk(node[0], node[1], node[3], node[4], t[5], t[6])


def replace(t, key, val, own=0):
    """Insert or overwrite ``key`` (map semantics) keeping keys unique."""
    return insert(delete(t, key), key, val, own)


def delete(t, key):
    if t is None:
        return None
    if key < t[0]:
        return _mk(t[0], t[1], _own(t), t[4], delete(t[5], key), t[6])
    if t[0] < key:
        return _mk(t[0], t[1], _own(t), t[4], t[5], delete(t[6], key))
    return merge(t[5], t[6])


def find(t, key):
    while t is not None:
        if key == t[0]:
            return t[4]
        t = t[5] if key < t[0] else t[6]
    return None


def count_lt(t, key):
    """Number of keys strictly below ``key``."""
    c = 0
    while t is not None:
        if t[0] < key:
            c += 1 + size(t[5])
            t = t[6]
        else:
            t = t[5]
    return c


def pop_min(t):
    """Return (key, val, rest) removing the smallest key; t must be nonempty."""
    if t[5] is None:
        return (t[0], t[4], t[6])
    key, val, rest = pop_min(t[5])
    return (key, val, _mk(t[0], t[1], _own(t), t[4], rest, t[6]))


def split_size(t, k):
    """Split into (first k keys in order, remaining keys)."""
    if k <= 0:
        return (None, t)
    if t is None:
        return (None, None)
    ls = size(t[5])
    if k <= ls:
        lo, rest = split_size(t[5], k)
        return (lo, _mk(t[0], t[1], _own(t), t[4], rest, t[6]))
    lo, rest = split_size(t[6], k - ls - 1)
    return (_mk(t[0], t[1], _own(t), t[4], t[5], lo), rest)


def split_bytes(t, cap):
    """Split into (longest key-order prefix with byte weight <= cap, suffix)."""
    if t is None:
        return (None, None)
    lb = bytsum(t[5])
    own = _own(t)
    if lb + own <= cap:
        keep, drop = split_bytes(t[6], cap - lb - own)
        return (_mk(t[0], t[1], own, t[4], t[5], keep), drop)
    keep, drop = split_bytes(t[5], cap)
    return (keep, _mk(t[0], t[1], own, t[4], drop, t[6]))


def items(t):
    """In-order list of (key, val)."""
    out = []
    stack = []
    while t is not None or stack:
        while t is not None:
            stack.append(t)
            t = t[5]
        t = stack.pop()
        out.append((t[0], t[4]))
        t = t[6]
    return out


def items_desc(t):
    return list(reversed(items(t)))

"""Rank policies for the branchable experiment engine.

Every policy assigns a rank on *every* enqueue attempt (rejected attempts
included).  Mutable policy state is captured by ``snapshot``/``restore`` so
checkpoint branches stay isolated.
"""
from treap import insert as _insert, replace as _replace, find as _find, items as _items


class SchedulingAlgorithm:
    def rank(self, pkt):
        raise NotImplementedError

    def feedback(self, rank):
        """Post-service update attached to a successful pop."""

    def snapshot(self):
        return None

    def restore(self, snap):
        pass

    def certificate(self):
        raise NotImplementedError


class FifoAlgorithm(SchedulingAlgorithm):
    """Increment a counter and use its new value as the rank."""

    def __init__(self):
        self.time = 0

    def rank(self, pkt):
        self.time += 1
        return self.time

    def snapshot(self):
        return self.time

    def restore(self, snap):
        self.time = snap

    def certificate(self):
        return {"kind": "fifo", "time": self.time}


class SpAlgorithm(SchedulingAlgorithm):
    """Configured strict-priority level per flow."""

    def __init__(self, levels):
        self.levels = dict(levels)

    def rank(self, pkt):
        return self.levels[pkt.flowid]

    def certificate(self):
        return {"kind": "sp",
                "levels": [[f, self.levels[f]] for f in sorted(self.levels)]}


class pFabricAlgorithm(SchedulingAlgorithm):
    """Shortest-flow-first: rank is the supplied flow size."""

    def __init__(self):
        pass

    def rank(self, pkt):
        return pkt.flow_size

    def certificate(self):
        return {"kind": "sff"}


class WFQAlgorithm(SchedulingAlgorithm):
    """Quantized finish tags: F[f] = max(F[f], V) + ceil(len*2^20 / w[f])."""

    def __init__(self, weights):
        self.virtual_time = 0
        self.weights = None   # flow -> weight
        self.finish = None    # flow -> finish tag
        for flow, weight in weights:
            self.weights = _insert(self.weights, flow, weight)
            self.finish = _insert(self.finish, flow, 0)

    def rank(self, pkt):
        weight = _find(self.weights, pkt.flowid)
        tag = _find(self.finish, pkt.flowid)
        floor = self.virtual_time
        if tag > floor:
            floor = tag
        tag = floor + (pkt.length * 1048576 + weight - 1) // weight
        self.finish = _replace(self.finish, pkt.flowid, tag)
        return tag

    def feedback(self, rank):
        if rank > self.virtual_time:
            self.virtual_time = rank

    def set_weight(self, flow, weight):
        self.weights = _replace(self.weights, flow, weight)

    def snapshot(self):
        return (self.virtual_time, self.finish, self.weights)

    def restore(self, snap):
        self.virtual_time, self.finish, self.weights = snap

    def certificate(self):
        return {"kind": "wfq",
                "virtual_time": self.virtual_time,
                "weights": [[f, w] for f, w in _items(self.weights)],
                "finish": [[f, v] for f, v in _items(self.finish)]}


def build_policy(spec):
    kind = spec["kind"]
    if kind == "fifo":
        return FifoAlgorithm()
    if kind == "sp":
        return SpAlgorithm(spec["levels"])
    if kind == "sff":
        return pFabricAlgorithm()
    if kind == "wfq":
        return WFQAlgorithm(spec["weights"])
    raise ValueError("unknown policy")
"""Experiment adapter: map a request batch onto scheduler runs."""
from scheduler import Engine


def run_request(request):
    """Return the response object for one complete request document."""
    runs = request["runs"]
    out = []
    for cfg in runs:
        engine = Engine(cfg)
        log = engine.run(cfg["events"])
        out.append({"log": log, "state": engine.certificate()})
    return {"runs": out}
#!/usr/bin/env python3
"""JSON entry point; all computation lives in the scheduling modules."""
import json
import math
import sys

sys.setrecursionlimit(50000)
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parent))
from utils import run_request


def pairs(items):
    result = {}
    for key, value in items:
        if key in result:
            raise ValueError('duplicate key')
        result[key] = value
    return result


def reject_constant(value):
    raise ValueError('nonfinite number')


def finite(value):
    if isinstance(value, float) and not math.isfinite(value):
        raise ValueError('nonfinite number')
    if isinstance(value, (dict, list)):
        for item in (value.values() if isinstance(value, dict) else value):
            finite(item)


def main():
    try:
        request = json.loads(sys.stdin.buffer.read().decode('utf-8'),
                             object_pairs_hook=pairs, parse_constant=reject_constant)
        finite(request)
        response = run_request(request)
    except (ValueError, UnicodeError, RecursionError, KeyError, TypeError,
            AttributeError, IndexError, OverflowError):
        print('{"error":"invalid"}')
        return
    print(json.dumps(response, separators=(',', ':'), allow_nan=False))


if __name__ == '__main__':
    main()
"""Immutable live-packet record.

A packet is created exactly once per enqueue attempt.  Every field is fixed at
creation so checkpoint snapshots can share packet objects safely.
"""


class Pkt:
    __slots__ = ("pktid", "flowid", "length", "flow_size", "rank", "ordinal",
                 "bank", "base")

    def __init__(self, pktid, flowid, length, flow_size, rank=0, ordinal=0,
                 bank=0, base=0):
        self.pktid = pktid
        self.flowid = flowid
        self.length = length
        self.flow_size = flow_size
        self.rank = rank
        self.ordinal = ordinal        # immutable tie ordinal: event index
        self.bank = bank              # dispatch bank; never relocated
        self.base = base              # lag reference count at admission

    def lag(self, served_above):
        """Live lag: higher-rank services observed while resident."""
        return served_above - self.base

